package com.rohit.inventory.service;
import com.rohit.inventory.dto.response.ReplenishmentRecommendationResponse; import com.rohit.inventory.entity.Inventory; import com.rohit.inventory.repository.InventoryRepository; import java.math.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ReplenishmentService { private final InventoryRepository inventory; public ReplenishmentService(InventoryRepository inventory){this.inventory=inventory;}
 @Transactional(readOnly=true) public List<ReplenishmentRecommendationResponse> recommendations(){Map<UUID,List<Inventory>> grouped=new HashMap<>();for(Inventory i:inventory.findAllActiveWithLocation())grouped.computeIfAbsent(i.getProduct().getId(),x->new ArrayList<>()).add(i);List<ReplenishmentRecommendationResponse> result=new ArrayList<>();for(List<Inventory> group:grouped.values()){BigDecimal reorder=group.get(0).getProduct().getReorderLevel();for(Inventory destination:group){BigDecimal available=destination.getAvailableQuantity();if(available.compareTo(reorder)>=0)continue;BigDecimal shortage=reorder.subtract(available);Inventory source=group.stream().filter(x->!x.getWarehouse().getId().equals(destination.getWarehouse().getId())).filter(x->x.getAvailableQuantity().compareTo(reorder)>0).max(Comparator.comparing(Inventory::getAvailableQuantity)).orElse(null);if(source==null)continue;BigDecimal surplus=source.getAvailableQuantity().subtract(reorder);BigDecimal quantity=shortage.min(surplus).setScale(3,RoundingMode.DOWN);if(quantity.signum()<=0)continue;int score=available.signum()==0?100:Math.min(99,shortage.multiply(BigDecimal.valueOf(100)).divide(reorder.max(BigDecimal.ONE),0,RoundingMode.HALF_UP).intValue());result.add(new ReplenishmentRecommendationResponse(destination.getProduct().getId(),destination.getProduct().getSku(),destination.getProduct().getName(),source.getWarehouse().getId(),source.getWarehouse().getName(),destination.getWarehouse().getId(),destination.getWarehouse().getName(),quantity,available,reorder,score,"Destination is below its reorder level while source has transferable surplus."));}}return result.stream().sorted(Comparator.comparingInt(ReplenishmentRecommendationResponse::priorityScore).reversed()).toList();}}
